1	// The verify-production code-work (#1530) — the I/O shell around probes.mjs. It
2	// runs Action-side, which is the whole reason this task exists: an agent session
3	// has no egress, so a verification whose artifact is a live URL (a Pages site, a
4	// deployed config) can only be read from here.
5	//
6	// Four verdicts, each its own exit:
7	//   invalid  — the spec is unreadable: the triage marker names every problem and
8	//              the exit is non-zero, so the item parks with the list.
9	//   not-live — a liveness probe failed: print the requeue marker with
10	//              now + Retry-every and exit clean; the executor re-arms the item.
11	//   pass     — comment the evidence on the item and exit clean; the executor
12	//              closes it done.
13	//   fail     — reopen Original-issue with the evidence (the verification did its
14	//              job by finding the fault, which is now that issue's), link it from
15	//              the item, and exit clean.
16	
17	import { pathToFileURL } from 'node:url';
18	import { humanTextOf } from '../../queue/work-item.mjs';
19	import { parseVerificationSpec, runProbes, renderResult } from './probes.mjs';
20	
21	const FETCH_TIMEOUT_MS = 30_000;
22	const BODY_CAP = 2 * 1024 * 1024;
23	
24	// One live fetch: bounded, redirect-following, body capped. A network error is
25	// retried once — a single blip must not reopen an issue — and the second failure
26	// is the answer.
27	export async function fetchOnce(url) {
28	  const attempt = async () => {
29	    const res = await fetch(url, { redirect: 'follow', signal: AbortSignal.timeout(FETCH_TIMEOUT_MS) });
30	    const body = (await res.text()).slice(0, BODY_CAP);
31	    return { status: res.status, body };
32	  };
33	  try { return await attempt(); } catch { return attempt(); }
34	}
35	
36	// The whole judgment, injectable for tests: reads the item, parses the spec out
37	// of the HUMAN half of its body (the machine block is the queue's), runs the
38	// probes, and lands the verdict's writes. Returns what main() turns into markers
39	// and an exit code.
40	export async function runVerification({ gh, repo, itemNumber, fetchUrl, now = () => new Date(), log = console.log }) {
41	  const { status, json: item } = await gh(`/repos/${repo}/issues/${itemNumber}`);
42	  if (status !== 200) throw new Error(`could not read item #${itemNumber}: ${status}`);
43	  const spec = parseVerificationSpec(humanTextOf(item.body));
44	  if (spec.problems.length) return { outcome: 'invalid', problems: spec.problems };
45	
46	  const live = await runProbes(spec.live, fetchUrl);
47	  for (const r of live) log(`liveness: ${renderResult(r)}`);
48	  if (!live.every((r) => r.ok)) {
49	    const firstFail = live.find((r) => !r.ok);
50	    return {
51	      outcome: 'not-live',
52	      until: new Date(now().getTime() + spec.retryEveryMs).toISOString(),
53	      reason: `not yet live: ${renderResult(firstFail)}`,
54	    };
55	  }
56	
57	  const verify = await runProbes(spec.verify, fetchUrl);
58	  for (const r of verify) log(`verify: ${renderResult(r)}`);
59	  const evidence = verify.map((r) => `- ${renderResult(r)}`).join('\n');
60	  if (verify.every((r) => r.ok)) {
61	    await gh(`/repos/${repo}/issues/${itemNumber}/comments`, {
62	      method: 'POST',
63	      body: { body: `Production verification PASSED. What was read:\n\n${evidence}` },
64	    });
65	    return { outcome: 'pass' };
66	  }
67	
68	  // The verification did its job by finding the fault — which is now the
69	  // original issue's, reopened with what was asserted and what was read.
70	  await gh(`/repos/${repo}/issues/${spec.originalIssue}`, { method: 'PATCH', body: { state: 'open' } });
71	  await gh(`/repos/${repo}/issues/${spec.originalIssue}/comments`, {
72	    method: 'POST',
73	    body: {
74	      body: `The production verification filed for this change (#${itemNumber}) FAILED against the live artifact:\n\n${evidence}\n\n`
75	        + 'The release is live (every liveness probe passed), so this is a fault in production, not a wait.',
76	    },
77	  });
78	  await gh(`/repos/${repo}/issues/${itemNumber}/comments`, {
79	    method: 'POST',
80	    body: { body: `Verification FAILED — reopened #${spec.originalIssue} with the evidence:\n\n${evidence}` },
81	  });
82	  return { outcome: 'fail', originalIssue: spec.originalIssue };
83	}
84	
85	export async function main() {
86	  const repo = process.env.CLAUDINITE_REPO;
87	  const itemNumber = Number(process.env.CLAUDINITE_ITEM);
88	  if (!repo || !itemNumber) throw new Error('CLAUDINITE_REPO / CLAUDINITE_ITEM not set — not running under the executor');
89	  if (!process.env.GITHUB_TOKEN) throw new Error('GITHUB_TOKEN is not set — the verification cannot read its item');
90	  const { makeGh } = await import('../../signals/gh.mjs');
91	  const verdict = await runVerification({ gh: makeGh(), repo, itemNumber, fetchUrl: fetchOnce });
92	
93	  if (verdict.outcome === 'invalid') {
94	    console.log(`claudinite-needs-human: action — this verification's probe spec is unreadable: ${verdict.problems.join('; ')}`);
95	    process.exit(1);
96	  }
97	  if (verdict.outcome === 'not-live') {
98	    console.log(`claudinite-requeue: ${verdict.until} — ${verdict.reason}`);
99	    return;
100	  }
101	  console.log(`verification ${verdict.outcome === 'pass' ? 'passed' : `failed — reopened #${verdict.originalIssue}`}`);
102	}
103	
104	// Run only when invoked directly (code-work's `node worker.mjs`), never on import.
105	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
106	  main().catch((e) => { console.error(`verify-production failed: ${e.message}`); process.exit(1); });
107	}
